TITLE_FRAMES = {
    "witness": "The Witness Frame (\"Caught on camera / on the record\") -- turns an observed moment into a documented account. Example: \"What her body language actually did the moment she decided you weren't a match.\"",
    "transformation": "Transformation Frame (\"Turning X into Y\") -- something broken or undervalued becomes valuable. Example: \"Turning a string of rejections into an effortless dating life.\"",
    "access": "Access Frame (\"Inside X\") -- implies hidden or normally-unseen access. Example: \"Inside a woman's subconscious safety checklist.\"",
    "warning": "Warning Frame (\"Don't / Never do X\") -- loss aversion and self-relevance. Example: \"Never say this on a first date if you want a second one.\"",
    "credibility": "Credibility Frame (age / tenure) -- personal experience as an instant credibility shortcut. Example: \"After 12 years studying attraction, here's the one question that decides everything.\"",
    "insider": "Insider Frame (\"Everyone / nobody is doing this\") -- exclusive in-group appeal. Example: \"The dating advice every confident man secretly ignores.\"",
    "forbidden": "Forbidden Frame (\"Banned / taboo\") -- scarcity and reactance. Example: \"The dating advice therapists won't say out loud.\"",
    "story": "Story Frame (\"How a [subject] did a surprising thing\") -- narrative instead of dry tutorial. Example: \"How one text message ended a six-month relationship.\"",
    "superlative": "Superlative Frame (\"Most / worst / biggest\") -- extreme scenario paired with a specific noun. Example: \"The most common mistake nice guys make on a first date.\"",
    "duration": "Duration Frame (\"X days / years\") -- a bounded timeframe that promises urgency or payoff. Example: \"What 90 days of no contact actually does to her feelings.\"",
}

FRAME_STACKING_NOTE = (
    "The strongest titles STACK 3-4 frames together rather than using just one. "
    "Example stacking Credibility + Access + Warning: "
    "\"After 12 years studying attraction, here's the subconscious red flag nobody warns you about.\""
)

HOOK_FRAMEWORK = """A winning hook does exactly two things: focuses the viewer on one single, unmistakable subject, and plants one exact question in every viewer's mind. A vague opening lets different viewers imagine different things, which fractures attention and causes drop-off the moment the next line doesn't match what they assumed.

Bad (vague, multiple possible meanings): "Here are some things I learned about dating."
Good (one subject, one question): "Here's the exact subconscious question that decides if she sees you as a partner or a friend."

Checklist for the hook: pick one subject, pick one specific question it plants, write it in 1-3 short sentences using plain, direct language with no filler, then check -- does this unmistakably point at ONE subject, and unmistakably plant ONE question? If not, rewrite it."""

REHOOK_TECHNIQUES = {
    "question_rehook": "Question Rehook -- directly address the viewer's internal skepticism mid-video. Example: \"Now you might be thinking: if this worked, why doesn't everyone do it? Here's where it actually falls apart for most people...\"",
    "tease_rehook": "Tease Rehook -- raise the stakes for something coming up. Example: \"Before we get to what actually works, there's one mistake that undoes all of it -- and almost everyone makes it.\"",
    "pattern_interrupt_rehook": "Pattern Interrupt Rehook -- a sudden shift in tone or rhythm right when the viewer's attention starts to settle into a predictable pattern, to jolt it back.",
    "hook_deliver_cycle": "Hook-Deliver Cycle -- never let a resolved question sit on a flat, comfortable note. The moment one question or mini-stakes resolves, immediately plant the next one. Place a rehook roughly every 2-3 minutes of runtime.",
}
